function circularSmoothElevations(arr: number[], passes = 2): number[] {
  let cur = [...arr];
  const w = [0.1, 0.22, 0.36, 0.22, 0.1];
  const n = cur.length;
  for (let p = 0; p < passes; p++) {
    const next = new Array<number>(n);
    for (let i = 0; i < n; i++) {
      let s = 0;
      for (let k = -2; k <= 2; k++) {
        s += cur[(i + k + n) % n] * w[k + 2];
      }
      next[i] = s;
    }
    cur = next;
  }
  const base = cur[0];
  return cur.map((v) => Math.round((v - base) * 100) / 100);
}

export const REAL_DEM_ELEVATIONS: Record<string, number[]> = Object.fromEntries(
  Object.entries(RAW_DEM_ELEVATIONS).map(([id, arr]) => [
    id,
    id === 'monaco'
      ? arr.map((v) => Math.round(v * 100) / 100)
      : circularSmoothElevations(arr, id === 'spa-francorchamps' || id === 'fuji' || id === 'hungaroring' || id === 'mexico-city' ? 3 : 2),
  ]),
);

